// Автосгенерировано из готовых образцов ТЭО (public/business-plans/<id>.docx)
// извлечением текста через pandoc — см. claude/gotovye-bp-i-ai-generator-status.md.
// Используется как заменитель веб-поиска для ИИ-генератора бизнес-планов
// (lib/ai/business-plan.ts) на бесплатном тарифе Gemini, где серверный
// веб-поиск недоступен: вместо живого поиска модель получает выдержки из
// уже готового банковского ТЭО-образца той же отрасли (анализ рынка,
// пример сметы/финансового плана, точку безубыточности, срок окупаемости,
// оценку рисков) — реальные ориентиры 2025-2026 года, собранные ранее.
// Если добавляется новая отрасль — здесь для неё записи не будет, промпт
// в lib/ai/business-plan.ts должен обрабатывать отсутствие записи (просто
// генерировать без образца, как раньше без веб-поиска).

export type BusinessPlanSampleContext = {
  /** Название отрасли, как оно фигурирует в самом образце */
  marketLabel: string;
  /** Краткое резюме примера проекта из образца */
  summary: string;
  /** Выдержка из раздела "Анализ рынка" образца */
  market: string;
  /** Выдержка из раздела "Маркетинговый план" образца */
  marketing: string;
  /** Выдержка из раздела "Финансовый план" (структура выручки/затрат) образца */
  financial: string;
  /** Точка безубыточности из образца */
  breakeven: string;
  /** Срок окупаемости и эффективность из образца */
  payback: string;
  /** Оценка рисков из образца */
  risks: string;
};

